/**
 * @summary Initializes a publisher
 *
 * @name base
 * @selector .slds-publisher
 * @restrict div
 * @support dev-ready
 * @variant
 */
.slds-publisher {
  display: flex;

  /**
   * @selector .slds-is-active
   * @restrict .slds-publisher
   * @modifier
   */
  &.slds-is-active {
    display: block;

    .slds-publisher__toggle-visibility {
      display: inherit;
      height: auto;
      overflow: visible;
      width: auto;
    }

    .slds-publisher__input {
      line-height: $line-height-text;
      height: auto;
      max-height: 10rem;
      resize: vertical;
      padding: {
        top: $spacing-small;
        bottom: $spacing-small;
      }
    }
  }

  /**
   *
   *
   * @selector .slds-publisher__toggle-visibility
   * @restrict .slds-publisher label, .slds-publisher ul
   * @required
   */
  .slds-publisher__toggle-visibility {
    display: block;
    height: 0;
    overflow: hidden;
    width: 0;
  }
}

/**
  * Abstraction of the text input styles
  *
  * @selector .slds-publisher__input
  * @restrict .slds-publisher textarea
  * @required
  */
.slds-publisher__input {
  line-height: $line-height-button;
  padding: 0 $spacing-medium;
  resize: none;
  max-height: calc(#{$line-height-button} + 2px);
  width: 100%;
  border-radius: $border-radius-medium;
}

/**
  * Bottom row of actionable items
  *
  * @selector .slds-publisher__actions
  * @restrict .slds-publisher div
  * @required
  */
.slds-publisher__actions > .slds-button {
  margin-left: $spacing-small;
}

// Lightning Design System 2.264.1
// Copyright (c) 2015-present, salesforce.com, inc. All rights reserved
// Licensed under BSD 3-Clause - see LICENSE.txt or git.io/sfdc-license

/**
 * @summary Initiates publisher that is specific to commenting in threads
 *
 * @name comment
 * @selector .slds-publisher_comment
 * @restrict .slds-publisher
 * @support dev-ready
 * @variant
 */
.slds-publisher_comment,
.slds-publisher--comment {
  @include form-input-container;
  position: relative;
  min-height: calc(#{$line-height-button} + 2px);
  max-height: calc(#{$line-height-button} + 2px);

  &.slds-is-active {
    min-height: $size-xx-small;
    max-height: $size-small;

    .slds-publisher__actions {
      display: flex;
    }
  }

  /**
   * Applies focus to comment publisher container when inside `textarea`
   *
   * @selector .slds-has-focus
   * @restrict .slds-publisher_comment
   * @notes Added through JavaScript
   * @modifier
   */
  &.slds-has-focus {
    box-shadow: var(--slds-g-shadow-outset-focus-1, #{$shadow-button-focus});
  }

  .slds-publisher__actions {
    display: none;
    padding: 0 $spacing-small $spacing-small;
  }

  .slds-attachments {
    padding: $spacing-x-small $spacing-small;
  }
}
